 // src/services/footballApi.js
import axios from 'axios'

// ============================================
// THESPORTSDB API (FREE - NO KEY REQUIRED)
// ============================================
const THESPORTSDB_URL = 'https://www.thesportsdb.com/api/v1/json/3'

// ============================================
// COMPETITIONS
// ============================================
export const COMPETITIONS = {
    PREMIER_LEAGUE: 'premier-league',
    LA_LIGA: 'la-liga',
    BUNDESLIGA: 'bundesliga',
    SERIE_A: 'serie-a',
    LIGUE_1: 'ligue-1',
    CHAMPIONS_LEAGUE: 'uefa-champions-league',
    PSL: 'psl',
}

// ============================================
// GET PSL MATCHES FROM THESPORTSDB
// ============================================
export async function getPSLMatches() {
    try {
        const today = new Date().toISOString().split('T')[0]
        const response = await axios.get(`${THESPORTSDB_URL}/eventsday.php`, {
            params: { d: today, l: 'South African Premier Division' }
        })
        
        if (response.data.events && response.data.events.length > 0) {
            return response.data.events
        }
        
        const upcomingResponse = await axios.get(`${THESPORTSDB_URL}/eventsnextleague.php`, {
            params: { id: 4358 }
        })
        
        if (upcomingResponse.data.events && upcomingResponse.data.events.length > 0) {
            return upcomingResponse.data.events
        }
        
        return getSamplePSLMatches()
        
    } catch (error) {
        console.error('PSL matches error:', error)
        return getSamplePSLMatches()
    }
}

// ============================================
// GET MATCHES BY COMPETITION
// ============================================
export async function getTodaysMatches(competition = 'premier-league') {
    try {
        if (competition === 'psl') {
            const pslMatches = await getPSLMatches()
            return pslMatches.map(m => formatMatch(m))
        }
        
        const today = new Date().toISOString().split('T')[0]
        const response = await axios.get(`https://sportscore.com/api/v1/football/matches/date/${today}`, {
            params: { competition: competition }
        })
        
        if (response.data && response.data.length > 0) {
            return response.data
        }
        
        return getSampleMatches()
        
    } catch (error) {
        console.error('Error fetching matches:', error)
        return getSampleMatches()
    }
}

// ============================================
// FORMAT MATCH FOR DISPLAY
// ============================================
export function formatMatch(match) {
    // Check if it's a TheSportsDB match (has strHomeTeam)
    if (match.strHomeTeam) {
        return {
            id: match.idEvent || `match-${Math.random()}`,
            matchId: match.idEvent || `match-${Math.random()}`,
            homeTeam: {
                name: match.strHomeTeam || 'Unknown',
                crest: match.strHomeTeamBadge || null,
                badge: getPSLTeamEmoji(match.strHomeTeam)
            },
            awayTeam: {
                name: match.strAwayTeam || 'Unknown',
                crest: match.strAwayTeamBadge || null,
                badge: getPSLTeamEmoji(match.strAwayTeam)
            },
            league: match.strLeague || 'PSL (South Africa)',
            leagueId: 'psl',
            kickoff: match.dateEvent || new Date().toISOString(),
            status: match.strStatus === 'FT' ? 'finished' : 'upcoming',
            score: {
                home: parseInt(match.intHomeScore) || 0,
                away: parseInt(match.intAwayScore) || 0
            },
            venue: match.strVenue || 'Unknown Venue',
            aiPrediction: generatePSLPrediction(match)
        }
    }
    
    // SportScore or other format
    return {
        id: match.id || `match-${Math.random()}`,
        matchId: match.id || `match-${Math.random()}`,
        homeTeam: {
            name: match.homeTeam?.name || match.home_team?.name || 'Unknown',
            crest: match.homeTeam?.logo || match.home_team?.logo || null,
            badge: getTeamEmoji(match.homeTeam?.name || match.home_team?.name)
        },
        awayTeam: {
            name: match.awayTeam?.name || match.away_team?.name || 'Unknown',
            crest: match.awayTeam?.logo || match.away_team?.logo || null,
            badge: getTeamEmoji(match.awayTeam?.name || match.away_team?.name)
        },
        league: match.league?.name || match.competition?.name || 'Unknown League',
        leagueId: match.league?.id || match.competition?.id || 'unknown',
        kickoff: match.kickoff || match.date || match.start_time || new Date().toISOString(),
        status: match.status || 'upcoming',
        score: {
            home: match.score?.home || match.home_score || 0,
            away: match.score?.away || match.away_score || 0
        },
        venue: match.venue || match.stadium || 'Unknown Venue',
        aiPrediction: generateAIPrediction(match)
    }
}

// ============================================
// GENERATE AI PREDICTION
// ============================================
function generateAIPrediction(match) {
    const homeScore = match.score?.home || match.home_score || 0
    const awayScore = match.score?.away || match.away_score || 0
    
    if (match.status === 'finished' || match.status === 'FT' || match.status === 'FINISHED') {
        return {
            result: {
                home: homeScore > awayScore ? 90 : 20,
                draw: homeScore === awayScore ? 80 : 15,
                away: awayScore > homeScore ? 90 : 20
            },
            confidence: 95,
            isFinished: true,
            actualScore: `${homeScore}-${awayScore}`
        }
    }
    
    const homeStrength = Math.random() * 0.4 + 0.3
    const awayStrength = Math.random() * 0.4 + 0.3
    
    let homeWin = Math.round((homeStrength / (homeStrength + awayStrength)) * 70 + 10)
    let awayWin = Math.round((awayStrength / (homeStrength + awayStrength)) * 70 + 10)
    let draw = 100 - homeWin - awayWin
    
    homeWin = Math.max(10, Math.min(80, homeWin))
    awayWin = Math.max(10, Math.min(80, awayWin))
    draw = Math.max(5, Math.min(40, draw))
    
    const total = homeWin + draw + awayWin
    if (total !== 100) {
        const diff = 100 - total
        homeWin += Math.round(diff / 2)
        awayWin += diff - Math.round(diff / 2)
    }
    
    return {
        result: {
            home: Math.max(10, Math.min(80, homeWin)),
            draw: Math.max(5, Math.min(40, draw)),
            away: Math.max(10, Math.min(80, awayWin))
        },
        yellowCards: {
            home: Math.floor(Math.random() * 3) + 1,
            away: Math.floor(Math.random() * 3) + 1
        },
        redCards: {
            home: Math.random() > 0.85 ? 1 : 0,
            away: Math.random() > 0.9 ? 1 : 0
        },
        corners: {
            home: Math.floor(Math.random() * 5) + 3,
            away: Math.floor(Math.random() * 5) + 3
        },
        confidence: Math.floor(Math.random() * 25) + 55
    }
}

// ============================================
// GENERATE PSL PREDICTION
// ============================================
function generatePSLPrediction(match) {
    return {
        result: {
            home: Math.floor(Math.random() * 40) + 20,
            draw: Math.floor(Math.random() * 30) + 10,
            away: Math.floor(Math.random() * 40) + 20
        },
        yellowCards: {
            home: Math.floor(Math.random() * 3) + 1,
            away: Math.floor(Math.random() * 3) + 1
        },
        redCards: {
            home: Math.random() > 0.85 ? 1 : 0,
            away: Math.random() > 0.9 ? 1 : 0
        },
        corners: {
            home: Math.floor(Math.random() * 5) + 3,
            away: Math.floor(Math.random() * 5) + 3
        },
        confidence: Math.floor(Math.random() * 25) + 55
    }
}

// ============================================
// PSL TEAM EMOJIS
// ============================================
function getPSLTeamEmoji(name) {
    if (!name) return '⚽'
    const emojis = {
        'Kaizer Chiefs': '⚪',
        'Orlando Pirates': '⚫',
        'Mamelodi Sundowns': '🟡',
        'SuperSport United': '🔵',
        'Cape Town City': '🔵',
        'Stellenbosch': '🟢',
        'Sekhukhune United': '🔴',
        'Polokwane City': '🟠',
        'Golden Arrows': '🟣',
        'Richards Bay': '🔵',
        'Chippa United': '🟡',
        'Royal AM': '🔴',
        'TS Galaxy': '⚪',
        'Moroka Swallows': '🔴',
        'AmaZulu': '🟢',
        'Marumo Gallants': '🔴'
    }
    for (const [key, emoji] of Object.entries(emojis)) {
        if (name.toLowerCase().includes(key.toLowerCase())) {
            return emoji
        }
    }
    return '⚽'
}

